param([string]$Exe="$PSScriptRoot/../FileTransferApp/x64/Debug/FileTransferAppGui.exe")
$ErrorActionPreference='Stop';. "$PSScriptRoot/n_to_1.ps1" -Exe $Exe -HelpersOnly
function U64([UInt64]$v){$b=New-Object byte[] 8;for($i=0;$i -lt 8;$i++){$b[$i]=($v -shr ((7-$i)*8))-band 255};return ,$b}
function Number([byte[]]$b){[UInt64]$n=0;for($i=0;$i -lt 8;$i++){$n=($n-shl 8)-bor $b[$i]};return $n}
function Digest([byte[]]$b){$h=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($h.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Spec([UInt64]$size,$name,$digest,$mode=0){$id=Digest ([byte[]]([Text.Encoding]::ASCII.GetBytes("FTA5`0")+(U64 $size)+[Text.Encoding]::ASCII.GetBytes($digest)+[Text.Encoding]::UTF8.GetBytes($name)));return @{ID=$id;Bytes=[byte[]]([Text.Encoding]::ASCII.GetBytes($id+$digest)+[byte]$mode+(U64 $size)+[Text.Encoding]::UTF8.GetBytes($name))}}
function Exact($stream,$n){$b=New-Object byte[] $n;$offset=0;while($offset -lt $n){$read=$stream.Read($b,$offset,$n-$offset);if(!$read){throw 'Unexpected close'};$offset+=$read};return ,$b}
function Frame($raw,[byte]$type,[UInt64]$id,[byte[]]$data=@()){$payload=[byte[]]((U64 $id)+$data);$n=$payload.Length;$header=[byte[]]@($type,(($n-shr 24)-band 255),(($n-shr 16)-band 255),(($n-shr 8)-band 255),($n-band 255));$raw.GetStream().Write($header,0,5);$raw.GetStream().Write($payload,0,$payload.Length)}
function Read-Frame($raw){$h=Exact $raw.GetStream() 5;$n=([int]$h[1]-shl 24)-bor([int]$h[2]-shl 16)-bor([int]$h[3]-shl 8)-bor $h[4];Assert ($n -ge 8 -and $n -le 1048576) 'Invalid response frame';$body=Exact $raw.GetStream() $n;$data=if($body.Length -gt 8){[byte[]]$body[8..($body.Length-1)]}else{[byte[]]@()};return @{Type=[int]$h[0];ID=(Number $body);Data=$data}}
function Expect($raw,$type){$f=Read-Frame $raw;if($f.Type -ne $type){$detail=if($f.Data){[Text.Encoding]::UTF8.GetString($f.Data)}else{''};throw ('Expected frame '+$type+' got '+$f.Type+' '+$detail)};return $f}
function Raw($s,$id){$r=[Net.Sockets.TcpClient]::new('127.0.0.1',$s.Port);$r.GetStream().ReadTimeout=8000;$line='FTA-C3|'+[Guid]::NewGuid().ToString('N')+'|'+[Guid]::NewGuid().ToString('N')+'|storage-peer|'+$id+'|C|M'+"`n";$b=[Text.Encoding]::UTF8.GetBytes($line);$r.GetStream().Write($b,0,$b.Length);$s.G.Wait(138,$id);$s.G.Click(139);$reply='';while(!$reply.EndsWith("`n")){$c=$r.GetStream().ReadByte();if($c -lt 0){throw 'Approval closed'};$reply+=[char]$c};Assert ($reply.StartsWith('FTA-A3|')) 'Manual approval failed';return $r}
function PathWait($p){$w=[Diagnostics.Stopwatch]::StartNew();while($w.ElapsedMilliseconds -lt 5000){if(Test-Path -LiteralPath $p){return};Start-Sleep -Milliseconds 20};throw "Missing file: $p"}
$s=$null;$a=$null;$b=$null;$idA=[Guid]::NewGuid().ToString('N');$idB=[Guid]::NewGuid().ToString('N')
try{
 $s=App 'server' $true 'storage-server';$a=Raw $s $idA;Count $s 1;$folderA=Join-Path $s.Dir ('received/peers/'+$idA)
 $bytes=New-Object byte[] (1MB);$bytes[0]=41;$spec=Spec $bytes.Length 'resume.bin' (Digest $bytes)
 Frame $a 6 2 $spec.Bytes;[void](Expect $a 7);Frame $a 2 2 $spec.Bytes
 for($i=0;$i -lt 4;$i++){Frame $a 3 2 ([byte[]]$bytes[($i*65536)..(($i+1)*65536-1)])}
 $part=Join-Path $folderA 'resume.bin.part';PathWait $part;$a.Dispose();$a=$null;Count $s 0;Assert ((Get-Item $part).Length -eq 262144) 'Checkpoint offset mismatch';$metadata=[MetadataProbe]::PathFor($s.Dir,$folderA,$spec.ID,$idA);PathWait $metadata;Pass 'disconnect preserves peer-scoped FTA record and partial data in default peer folder'
 $s.G.Close();$s.G.Dispose();$s=App 'server';$a=Raw $s $idA;Count $s 1;$resume=Spec $bytes.Length 'resume.bin' (Digest $bytes) 1
 Frame $a 6 2 $resume.Bytes;$ack=Expect $a 7;Assert ((Number $ack.Data) -eq 262144) 'Resume offset mismatch';Frame $a 2 2 $resume.Bytes
 for($i=4;$i -lt 16;$i++){Frame $a 3 2 ([byte[]]$bytes[($i*65536)..(($i+1)*65536-1)])};Frame $a 4 2;[void](Expect $a 5)
 $saved=Join-Path $folderA 'resume.bin';Assert ((Get-FileHash $saved).Hash.ToLowerInvariant() -eq (Digest $bytes)) 'Resumed content mismatch';Assert (!(Test-Path $part)) 'Part retained after commit';Pass 'server restart resumes same PeerId at exact offset and verifies SHA-256 and stored ACK'
 $query=Spec $bytes.Length 'resume.bin' (Digest $bytes) 2;Frame $a 6 4 $query.Bytes;[void](Expect $a 11);Pass 'same peer completion query is idempotent'
 $b=Raw $s $idB;Count $s 2;$s.G.SelectSession($idB);$s.G.Folder($folderA,$false,155)
 Frame $b 6 2 $query.Bytes;[void](Expect $b 9);Pass 'different PeerId cannot discover another peer recovery record in a shared custom folder'
 $foreign=[MetadataProbe]::PathFor($s.Dir,$folderA,$spec.ID,$idB);Copy-Item -LiteralPath $metadata -Destination $foreign
 Frame $b 6 4 $query.Bytes;[void](Expect $b 9);Assert ((Get-FileHash $saved).Hash.ToLowerInvariant() -eq (Digest $bytes)) 'Foreign resume modified committed file';Pass 'copying encrypted metadata to another PeerId still fails protected owner validation'
 $invalid=Folder 'will-disappear';$s.G.Folder($invalid,$false,155);Start-Sleep -Milliseconds 200;Remove-Item -LiteralPath $invalid
 $small=Spec 1 'invalid.bin' (Digest ([byte[]]@(1)));Frame $b 6 6 $small.Bytes;[void](Expect $b 9);Assert (!(Test-Path (Join-Path $folderA 'invalid.bin'))) 'Invalid folder fell back to old destination';Pass 'invalid configured folder refuses automatic preparation without fallback'
 $s.G.Click(156);$folderB=Join-Path $s.Dir ('received/peers/'+$idB);$s.G.Wait(154,$folderB);PathWait $folderB
 $drive=[IO.DriveInfo]::new([IO.Path]::GetPathRoot($folderB));[UInt64]$tooLarge=$drive.AvailableFreeSpace+64MB;Assert ($tooLarge -le 1TB) 'Disk-space fixture exceeds wire size cap';$large=Spec $tooLarge 'space.bin' ('0'*64);Frame $b 6 8 $large.Bytes;$spaceReply=Expect $b 9;Assert ([Text.Encoding]::UTF8.GetString($spaceReply.Data).Contains('Insufficient disk space')) 'Wrong storage error';Pass 'per-peer automatic receive checks available disk space'
 $cancel=Spec 1 'cancel.bin' (Digest ([byte[]]@(1)));Frame $b 6 10 $cancel.Bytes;[void](Expect $b 7);Frame $b 10 10;[void](Expect $b 10);Start-Sleep -Milliseconds 200;Assert (!(Test-Path (Join-Path $folderB 'cancel.bin.part'))) 'Cancelled owned part retained';Pass 'per-peer cancellation preserves other session and removes its own uncommitted data'
 $partial=Spec $bytes.Length 'mode-change.bin' (Digest $bytes);Frame $b 6 12 $partial.Bytes;[void](Expect $b 7);Frame $b 2 12 $partial.Bytes;Frame $b 3 12 ([byte[]]$bytes[0..65535]);$modePart=Join-Path $folderB 'mode-change.bin.part';PathWait $modePart
 $s.G.SetRole($false);$s.G.ApplyProfileWithConfirmation($false);Count $s 2;Assert (Test-Path $modePart) 'Cancelled role change removed active data';Pass 'role change confirmation cancellation leaves sessions and transfer intact'
 $s.G.SetRole($false);$s.G.ApplyProfileWithConfirmation($true);$s.G.Wait(141,'role=client');Count $s 0;Assert (Test-Path $modePart) 'Role switch deleted checkpoint';PathWait ([MetadataProbe]::PathFor($s.Dir,$folderB,$partial.ID,$idB));Pass 'confirmed role change closes workers and preserves recoverable metadata'
 $s.G.SetRole($true);$s.G.Click(151);$s.G.Wait(141,'role=server');$s.G.Close();$s.G.Dispose();$settings=Join-Path $s.Dir 'gui-settings.txt.multiclient';[IO.File]::WriteAllBytes($settings,[byte[]](1..100));$s=App 'server';$s.G.Wait(108,'Settings error:');Assert ((Get-Item $settings).Length -eq 100) 'Corrupt settings silently overwritten';Assert ($s.G.Text(141).Contains('role=client')) 'Damaged server settings retained automatic server role';Pass 'corrupt protected settings are preserved and fail closed with visible diagnostic'
}finally{foreach($r in @($a,$b)){if($r){$r.Dispose()}};if($s){try{[IO.File]::WriteAllText((Join-Path $s.Dir 'ui.log'),$s.G.Text(108))}catch{};try{$s.G.Dispose()}catch{}};"N1 storage artifacts: $run"}
